 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, color, mix, smoothstep, fract, sin, dot } from 'three/tsl';
import { gsap } from 'gsap';

function disposeObject3D(obj) {
  obj.traverse((o) => {
    if (o.geometry) o.geometry.dispose();
    if (o.material) {
      if (Array.isArray(o.material)) {
        o.material.forEach((m) => m?.dispose?.());
      } else {
        o.material?.dispose?.();
      }
    }
  });
}

export default function createNode(config, ctx) {
  const { THREE, textureLoader, fontAtlas } = ctx;

  const group = new THREE.Group();
  group.scale.setScalar(0.96);

  const palette = config.intent?.visualSpec?.colors || config.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const textItems =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];
  const headline = textItems.find((i) => i.role === 'headline') || textItems[0];

  // ---- engineered gradient backdrop with subtle grain ----
  const u = uv();
  const t = smoothstep(0.0, 1.0, u.y);
  const grad = mix(color(palette.ink), color(palette.surface), t);

  const noiseCoord = u.mul(vec2(12.9898, 78.233));
  const grain = fract(sin(dot(noiseCoord, vec2(1.0, 1.0))).mul(43758.5453))
    .sub(0.5)
    .mul(0.035);

  const surfaceNode = grad.add(grain);

  const bgMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.95,
    side: THREE.DoubleSide,
  });
  bgMat.colorNode = surfaceNode;

  const bgGeo = new THREE.PlaneGeometry(4.5, 2.0);
  const bgMesh = new THREE.Mesh(bgGeo, bgMat);
  bgMesh.position.z = -0.25;
  group.add(bgMesh);

  // ---- foreground textured plane ----
  const imgMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.95,
    side: THREE.DoubleSide,
    depthWrite: false,
  });
  const imgGeo = new THREE.PlaneGeometry(3.2, 2.0);
  const imgMesh = new THREE.Mesh(imgGeo, imgMat);
  imgMesh.position.z = 0.05;
  group.add(imgMesh);

  let loadedTexture = null;
  if (config.imageUrl) {
    textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      imgMat.map = tex;
      imgMat.needsUpdate = true;
    });
  }

  // ---- headline text ----
  let textGroup = null;
  if (headline) {
    const fontSize =
      headline.typography?.fontSize != null ? headline.typography.fontSize : 0.62;
    textGroup = fontAtlas.createText(String(headline.text), {
      fontSize: typeof fontSize === 'number' ? fontSize : 0.62,
      color: palette.paper,
      align: 'center',
    });
    textGroup.position.set(0, 0.05, 0.12);
    group.add(textGroup);
  }

  // ---- small accent underline (<=10% frame) ----
  const accentGeo = new THREE.PlaneGeometry(0.38, 0.04);
  const accentMat = new MeshBasicNodeMaterial({
    color: palette.accent,
    transparent: true,
    opacity: 0.9,
  });
  const accentMesh = new THREE.Mesh(accentGeo, accentMat);
  accentMesh.position.set(0, -0.45, 0.15);
  group.add(accentMesh);

  // ---- load entrance ----
  const timelines = [];
  const tl = gsap.timeline();
  tl.fromTo(
    group.position,
    { y: 0.2 },
    { y: 0, duration: 0.72, ease: 'power3.out' },
    0
  );
  tl.fromTo(
    group.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    { x: 1, y: 1, z: 1, duration: 0.8, ease: 'power2.out' },
    0
  );
  timelines.push(tl);

  // ---- userData contract ----
  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    if (loadedTexture) loadedTexture.dispose();
    if (imgMat.map && imgMat.map !== loadedTexture) imgMat.map.dispose();
    imgMat.dispose();
    bgMat.dispose();
    accentMat.dispose();
    disposeObject3D(group);
  };

  return group;
}
